      "מֵאֵימָתַי כָּל אָדָם מֻתָּרִין בְּלֶקֶט. מִשֶּׁיֵּלְכוּ הַנָּמוֹשׁוֹת. בְּפֶרֶט וְעוֹלְלוֹת, מִשֶּׁיֵּלְכוּ הָעֲנִיִּים בַּכֶּרֶם וְיָבֹאוּ. וּבְזֵיתִים, מִשֶּׁתֵּרֵד רְבִיעָה שְׁנִיָּה. אָמַר רַבִּי יְהוּדָה, וַהֲלֹא יֵשׁ שֶׁאֵינָם מוֹסְקִין אֶת זֵיתֵיהֶם אֶלָּא לְאַחַר רְבִיעָה שְׁנִיָּה. אֶלָּא כְדֵי שֶׁיְּהֵא הֶעָנִי יוֹצֵא וְלֹא יְהֵא מֵבִיא בְּאַרְבָּעָה אִסָּרוֹת:",
      "נֶאֱמָנִים עַל הַלֶּקֶט וְעַל הַשִּׁכְחָה וְעַל הַפֵּאָה בִּשְׁעָתָן, וְעַל מַעְשַׂר עָנִי בְּכָל שְׁנָתוֹ. וּבֶן לֵוִי נֶאֱמָן לְעוֹלָם. וְאֵינָן נֶאֱמָנִין אֶלָּא עַל דָּבָר שֶׁבְּנֵי אָדָם נוֹהֲגִין כֵּן:",
      "נֶאֱמָנִין עַל הַחִטִּים, וְאֵין נֶאֱמָנִין עַל הַקֶּמַח וְלֹא עַל הַפָּת. נֶאֱמָנִין עַל הַשְּׂעוֹרָה שֶׁל אֹרֶז, וְאֵין נֶאֱמָנִין עָלָיו בֵּין חַי בֵּין מְבֻשָּׁל. נֶאֱמָנִין עַל הַפּוֹל, וְאֵין נֶאֱמָנִין עַל הַגְּרִיסִין, לֹא חַיִּים וְלֹא מְבֻשָּׁלִין. נֶאֱמָנִין עַל הַשֶּׁמֶן לוֹמַר שֶׁל מַעְשַׂר עָנִי הוּא, וְאֵין נֶאֱמָנִין עָלָיו לוֹמַר שֶׁל זֵיתֵי נִקּוּף הוּא:",
      "נֶאֱמָנִים עַל הַיָּרָק חַי, וְאֵין נֶאֱמָנִים עַל הַמְבֻשָּׁל, אֶלָּא אִם כֵּן הָיָה לוֹ דָּבָר מֻעָט, שֶׁכֵּן דֶּרֶךְ בַּעַל הַבַּיִת לִהְיוֹת מוֹצִיא מִלְּפָסוֹ:",
      "אֵין פּוֹחֲתִין לָעֲנִיִּים בַּגֹּרֶן מֵחֲצִי קַב חִטִּים וְקַב שְׂעוֹרִים. רַבִּי מֵאִיר אוֹמֵר, חֲצִי קַב. קַב וָחֵצִי כֻסְּמִין, וְקַב גְּרוֹגָרוֹת, אוֹ מָנֶה דְּבֵלָה. רַבִּי עֲקִיבָא אוֹמֵר, פְּרָס. חֲצִי לֹג יָיִן. רַבִּי עֲקִיבָא אוֹמֵר, רְבִיעִית. רְבִיעִית שֶׁמֶן. רַבִּי עֲקִיבָא אוֹמֵר, שְׁמִינִית. וּשְׁאָר כָּל הַפֵּרוֹת, אָמַר אַבָּא שָׁאוּל, כְּדֵי שֶׁיִּמְכְּרֵם וְיִקַּח בָּהֶם מְזוֹן שְׁתֵּי סְעֻדּוֹת:",
      "מִדָּה זוֹ אֲמוּרָה בְּכֹהֲנִים וּבִלְוִיִּם וּבְיִשְׂרְאֵלִים. הָיָה מַצִּיל, נוֹטֵל מֶחֱצָה וְנוֹתֵן מֶחֱצָה. הָיָה לוֹ דָבָר מֻעָט, נוֹתֵן לִפְנֵיהֶם, וְהֵן מְחַלְּקִין בֵּינֵיהֶם:",
      "אֵין פּוֹחֲתִין לֶעָנִי הָעוֹבֵר מִמָּקוֹם לְמָקוֹם מִכִּכָּר בְּפוּנְדְיוֹן, מֵאַרְבַּע סְאִין בְּסֶלַע. לָן, נוֹתְנִין לוֹ פַּרְנָסַת לִינָה. שָׁבַת, נוֹתְנִין לוֹ מְזוֹן שָׁלשׁ סְעֻדּוֹת. מִי שֶׁיֶּשׁ לוֹ מְזוֹן שְׁתֵּי סְעֻדּוֹת, לֹא יִטֹּל מִן הַתַּמְחוּי. מְזוֹן אַרְבַּע עֶשְׂרֵה סְעֻדּוֹת, לֹא יִטֹּל מִן הַקֻּפָּה. וְהַקֻּפָּה נִגְבֵּית בִּשְׁנַיִם, וּמִתְחַלֶּקֶת בִּשְׁלשָׁה:",
      "מִי שֶׁיֶּשׁ לוֹ מָאתַיִם זוּז, לֹא יִטֹּל לֶקֶט שִׁכְחָה וּפֵאָה וּמַעְשַׂר עָנִי. הָיוּ לוֹ מָאתַיִם חָסֵר דִּינָר, אֲפִלּוּ אֶלֶף נוֹתְנִין לוֹ כְאַחַת, הֲרֵי זֶה יִטֹּל. הָיוּ מְמֻשְׁכָּנִים לְבַעַל חוֹבוֹ אוֹ לִכְתֻבַּת אִשְׁתּוֹ, הֲרֵי זֶה יִטֹּל. אֵין מְחַיְּבִין אוֹתוֹ לִמְכֹּר אֶת בֵּיתוֹ וְאֶת כְּלֵי תַשְׁמִישׁוֹ:",
      "מִי שֶׁיֶּשׁ לוֹ חֲמִשִּׁים זוּז וְהוּא נוֹשֵׂא וְנוֹתֵן בָּהֶם, הֲרֵי זֶה לֹא יִטֹּל. וְכָל מִי שֶׁאֵינוֹ צָרִיךְ לִטֹּל וְנוֹטֵל, אֵינוֹ נִפְטָר מִן הָעוֹלָם עַד שֶׁיִּצְטָרֵךְ לַבְּרִיּוֹת. וְכָל מִי שֶׁצָּרִיךְ לִטֹּל וְאֵינוֹ נוֹטֵל, אֵינוֹ מֵת מִן הַזִּקְנָה עַד שֶׁיְּפַרְנֵס אֲחֵרִים מִשֶּׁלּוֹ, וְעָלָיו הַכָּתוּב אוֹמֵר בָּרוּךְ הַגֶּבֶר אֲשֶׁר יִבְטַח בַּה' וְהָיָה ה' מִבְטַחוֹ (ירמיה יז). וְכֵן דַּיָּן שֶׁדָּן דִּין אֱמֶת לַאֲמִתּוֹ. וְכָל מִי שֶׁאֵינוֹ לֹא חִגֵּר, וְלֹא סוּמָא, וְלֹא פִסֵּחַ, וְעוֹשֶׂה עַצְמוֹ כְּאַחַד מֵהֶם, אֵינוֹ מֵת מִן הַזִּקְנָה עַד שֶׁיִּהְיֶה כְּאֶחָד מֵהֶם, שֶׁנֶּאֱמַר (דברים טז) צֶדֶק צֶדֶק תִּרְדֹּף. וְכָל דַּיָּן שֶׁלּוֹקֵחַ שֹׁחַד וּמַטֶּה אֶת הַדִּין, אֵינוֹ מֵת מִן הַזִּקְנָה עַד שֶׁעֵינָיו כֵּהוֹת, שֶׁנֶּאֱמַר (שמות כג) וְשֹׁחַד לֹא תִקָּח כִּי הַשֹּׁחַד יְעַוֵּר פִּקְחִים וְגוֹ': סְלִיק מַסֶּכֶת פֵּאָה"
