      "הָאִשָּׁה שֶׁהָיְתָה אוֹכֶלֶת בִּתְרוּמָה, בָּאוּ וְאָמְרוּ לָהּ, מֵת בַּעְלִיךְ אוֹ גֵרְשֵׁךְ, וְכֵן הָעֶבֶד שֶׁהָיָה אוֹכֵל בִּתְרוּמָה, וּבָאוּ וְאָמְרוּ לוֹ, מֵת רַבָּךְ, אוֹ מְכָרָךְ לְיִשְׂרָאֵל, אוֹ נְתָנָךְ בְּמַתָּנָה, אוֹ עֲשָׂאָךְ בֶּן חוֹרִין. וְכֵן כֹּהֵן שֶׁהָיָה אוֹכֵל בִּתְרוּמָה, וְנוֹדַע שֶׁהוּא בֶן גְּרוּשָׁה אוֹ בֶן חֲלוּצָה, רַבִּי אֱלִיעֶזֶר מְחַיֵּב קֶרֶן וְחֹמֶשׁ, וְרַבִּי יְהוֹשֻׁעַ פּוֹטֵר. הָיָה עוֹמֵד וּמַקְרִיב עַל גַּבֵּי הַמִּזְבֵּחַ, וְנוֹדַע שֶׁהוּא בֶן גְּרוּשָׁה אוֹ בֶן חֲלוּצָה, רַבִּי אֱלִיעֶזֶר אוֹמֵר, כָּל הַקָּרְבָּנוֹת שֶׁהִקְרִיב עַל גַּבֵּי הַמִּזְבֵּחַ, פְּסוּלִים. וְרַבִּי יְהוֹשֻׁעַ מַכְשִׁיר. נוֹדַע שֶׁהוּא בַעַל מוּם, עֲבוֹדָתוֹ פְּסוּלָה:",
      "וְכֻלָּם, שֶׁהָיְתָה תְרוּמָה בְתוֹךְ פִּיהֶם, רַבִּי אֱלִיעֶזֶר אוֹמֵר, יִבְלְעוּ. וְרַבִּי יְהוֹשֻׁעַ אוֹמֵר, יִפְלֹטוּ. אָמְרוּ לוֹ, נִטְמֵאתָ וְנִטְמֵאת תְּרוּמָה, רַבִּי אֱלִיעֶזֶר אוֹמֵר, יִבְלָע. וְרַבִּי יְהוֹשֻׁעַ אוֹמֵר, יִפְלֹט. טָמֵא הָיִיתָ וּטְמֵאָה הָיְתָה תְרוּמָה, אוֹ נוֹדַע שֶׁהוּא טֶבֶל, וּמַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה תְרוּמָתוֹ, וּמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ, אוֹ שֶׁטָּעַם טַעַם פִּשְׁפֵּשׁ לְתוֹךְ פִּיו, הֲרֵי זֶה יִפְלֹט:",
      "הָיָה אוֹכֵל בְּאֶשְׁכּוֹל וְנִכְנַס מִן הַגִּנָּה לֶחָצֵר, רַבִּי אֱלִיעֶזֶר אוֹמֵר, יִגְמֹר. וְרַבִּי יְהוֹשֻׁעַ אוֹמֵר, לֹא יִגְמֹר. חֲשֵׁכָה לֵילֵי שַׁבָּת, רַבִּי יְהוֹשֻׁעַ אוֹמֵר, יִגְמֹר. וְרַבִּי אֱלִיעֶזֶר אוֹמֵר, לֹא יִגְמֹר:",
      "יַיִן שֶׁל תְּרוּמָה שֶׁנִּתְגַּלָּה, יִשָּׁפֵךְ, וְאֵין צָרִיךְ לוֹמַר שֶׁל חֻלִּין. שְׁלֹשָׁה מַשְׁקִין אֲסוּרִים מִשּׁוּם גִּלּוּי, הַמַּיִם וְהַיַּיִן וְהֶחָלָב. וּשְׁאָר כָּל הַמַּשְׁקִין מֻתָּרִים. כַּמָּה יִשְׁהוּ וְיִהְיוּ אֲסוּרִין, כְּדֵי שֶׁיֵּצֵא הָרַחַשׁ מִמָּקוֹם קָרוֹב וְיִשְׁתֶּה:",
      "שִׁעוּר הַמַּיִם הַמְגֻלִּין, כְּדֵי שֶׁתֹּאבַד בָּהֶם הַמָּרָה. רַבִּי יוֹסֵי אוֹמֵר, בְּכֵלִים, כָּל שֶׁהֵן, וּבַקַּרְקָעוֹת, אַרְבָּעִים סְאָה:",
      "נִקּוּרֵי תְאֵנִים וַעֲנָבִים וְקִשּׁוּאִין וְהַדְּלוּעִין וְהָאֲבַטִּיחִים וְהַמְּלָפְפוֹנוֹת, אֲפִלּוּ הֵם כִּכָּר, אֶחָד גָּדוֹל וְאֶחָד קָטָן, אֶחָד תָּלוּשׁ וְאֶחָד מְחֻבָּר, כָּל שֶׁיֶּשׁ בּוֹ לֵחָה, אָסוּר. וּנְשׁוּכַת הַנָּחָשׁ, אֲסוּרָה, מִפְּנֵי סַכָּנַת נְפָשׁוֹת:",
      "הַמְשַׁמֶּרֶת שֶׁל יַיִן, אֲסוּרָה מִשּׁוּם גִּלּוּי. רַבִּי נְחֶמְיָה מַתִּיר:",
      "חָבִית שֶׁל תְּרוּמָה שֶׁנּוֹלַד בָּהּ סְפֵק טֻמְאָה, רַבִּי אֱלִיעֶזֶר אוֹמֵר, אִם הָיְתָה מֻנַּחַת בִּמְקוֹם תֻּרְפָּה, יַנִּיחֶנָּה בְּמָקוֹם הַמֻּצְנָע, וְאִם הָיְתָה מְגֻלָּה, יְכַסֶּנָּה. וְרַבִּי יְהוֹשֻׁעַ אוֹמֵר, אִם הָיְתָה מֻנַּחַת בְּמָקוֹם מֻצְנָע, יַנִּיחֶנָּה בִּמְקוֹם תֻּרְפָּה, וְאִם הָיְתָה מְכֻסָּה, יְגַלֶּנָּה. רַבָּן גַּמְלִיאֵל אוֹמֵר, אַל יְחַדֵּשׁ בָּהּ דָּבָר:",
      "חָבִית שֶׁנִּשְׁבְּרָה בַּגַּת הָעֶלְיוֹנָה, וְהַתַּחְתּוֹנָה טְמֵאָה, מוֹדֶה רַבִּי אֱלִיעֶזֶר וְרַבִּי יְהוֹשֻׁעַ, שֶׁאִם יְכוֹלִים לְהַצִּיל מִמֶּנָּה רְבִיעִית בְּטָהֳרָה, יַצִּיל. וְאִם לָאו, רַבִּי אֱלִיעֶזֶר אוֹמֵר, תֵּרֵד וְתִטַּמֵּא, וְאַל יְטַמְּאֶנָּה בְיָדָיו:",
      "וְכֵן חָבִית שֶׁל שֶׁמֶן שֶׁנִּשְׁפְּכָה, מוֹדֶה רַבִּי אֱלִיעֶזֶר וְרַבִּי יְהוֹשֻׁעַ, שֶׁאִם יָכוֹל לְהַצִּיל מִמֶּנָּה רְבִיעִית בְּטָהֳרָה, יַצִּיל. וְאִם לָאו, רַבִּי אֱלִיעֶזֶר אוֹמֵר, תֵּרֵד וְתִבָּלַע, וְאַל יְבַלְּעֶנָּה בְיָדָיו:",
      "וְעַל זוֹ וְעַל זוֹ אָמַר רַבִּי יְהוֹשֻׁעַ, לֹא זוֹ הִיא תְרוּמָה שֶׁאֲנִי מֻזְהָר עָלֶיהָ מִלְּטַמְּאָהּ, אֶלָּא מִלְּאָכְלָהּ. וּבַל תְּטַמְּאָהּ כֵּיצַד, הָיָה עוֹבֵר מִמָּקוֹם לְמָקוֹם וְכִכָּרוֹת שֶׁל תְּרוּמָה בְיָדוֹ, אָמַר לוֹ נָכְרִי, תֶּן לִי אַחַת מֵהֶן וַאֲטַמְּאָהּ, וְאִם לָאו, הֲרֵי אֲנִי מְטַמֵּא אֶת כֻּלָּהּ, רַבִּי אֱלִיעֶזֶר אוֹמֵר, יְטַמֵּא אֶת כֻּלָּהּ, וְאַל יִתֶּן לוֹ אַחַת מֵהֶן וִיטַמֵּא. רַבִּי יְהוֹשֻׁעַ אוֹמֵר, יַנִּיחַ לְפָנָיו אַחַת מֵהֶן עַל הַסָּלַע:",
