      "כֶּרֶם רְבָעִי, מְצַיְּנִין אוֹתוֹ בְּקוֹזְזוֹת אֲדָמָה, וְשֶׁל עָרְלָה בְּחַרְסִית, וְשֶׁל קְבָרוֹת בְּסִיד, וּמְמַחֶה וְשׁוֹפֵךְ. אָמַר רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל, בַּמֶּה דְבָרִים אֲמוּרִים, בַּשְּׁבִיעִית. וְהַצְּנוּעִים מַנִּיחִין אֶת הַמָּעוֹת וְאוֹמְרִים, כָּל הַנִּלְקָט מִזֶּה, יְהֵא מְחֻלָּל עַל הַמָּעוֹת הָאֵלּוּ:",
      "כֶּרֶם רְבָעִי הָיָה עוֹלֶה לִירוּשָׁלַיִם מַהֲלַךְ יוֹם אֶחָד לְכָל צָד. וְאֵיזוֹ הִיא תְחוּמָהּ, אֵילַת מִן הַדָּרוֹם וְעַקְרַבַּת מִן הַצָּפוֹן, לוֹד מִן הַמַּעֲרָב וְהַיַּרְדֵּן מִן הַמִּזְרָח. וּמִשֶּׁרַבּוּ הַפֵּרוֹת, הִתְקִינוּ שֶׁיְּהֵא נִפְדֶּה סָמוּךְ לַחוֹמָה. וּתְנַאי הָיָה הַדָּבָר, שֶׁאֵימָתַי שֶׁיִּרְצוּ, יַחֲזֹר הַדָּבָר לִכְמוֹת שֶׁהָיָה. רַבִּי יוֹסֵי אוֹמֵר, מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ, הָיָה הַתְּנַאי הַזֶּה. וּתְנַאי הָיָה, אֵימָתַי שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ, יַחֲזֹר הַדָּבָר לִכְמוֹת שֶׁהָיָה:",
      "כֶּרֶם רְבָעִי, בֵּית שַׁמַּאי אוֹמְרִים, אֵין לוֹ חֹמֶשׁ וְאֵין לוֹ בִעוּר. וּבֵית הִלֵּל אוֹמְרִים, יֶשׁ לוֹ. בֵּית שַׁמַּאי אוֹמְרִים, יֶשׁ לוֹ פֶרֶט וְיֶשׁ לוֹ עוֹלְלוֹת, וְהָעֲנִיִּים פּוֹדִין לְעַצְמָן. וּבֵית הִלֵּל אוֹמְרִים, כֻּלּוֹ לַגָּת:",
      "כֵּיצַד פּוֹדִין נֶטַע רְבָעִי, מַנִּיחַ אֶת הַסַּל עַל פִּי שְׁלֹשָׁה, וְאוֹמֵר, כַּמָּה אָדָם רוֹצֶה לִפְדּוֹת לוֹ בְסֶלַע עַל מְנָת לְהוֹצִיא יְצִיאוֹת מִבֵּיתוֹ. וּמַנִּיחַ אֶת הַמָּעוֹת, וְאוֹמֵר, כָּל הַנִּלְקָט מִזֶּה, מְחֻלָּל עַל הַמָּעוֹת הָאֵלּוּ בְּכָךְ וְכָךְ סַלִּים בְּסָלַע:",
      "וּבַשְּׁבִיעִית, פּוֹדֵהוּ בְשָׁוְיוֹ. וְאִם הָיָה הַכֹּל מֻפְקָר, אֵין לוֹ אֶלָּא שְׂכַר לְקִיטָה. הַפּוֹדֶה נֶטַע רְבָעִי שֶׁלּוֹ, מוֹסִיף עָלָיו חֲמִשִּׁיתוֹ, בֵּין שֶׁהוּא שֶׁלּוֹ וּבֵין שֶׁנִּתַּן לוֹ בְּמַתָּנָה:",
      "עֶרֶב יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח שֶׁל רְבִיעִית וְשֶׁל שְׁבִיעִית, הָיָה בִעוּר. כֵּיצַד הָיָה בִעוּר, נוֹתְנִין תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר לַבְּעָלִים, וּמַעֲשֵׂר רִאשׁוֹן לִבְעָלָיו, וּמַעֲשַׂר עָנִי לִבְעָלָיו. וּמַעֲשֵׂר שֵׁנִי וְהַבִּכּוּרִים מִתְבַּעֲרִים בְּכָל מָקוֹם. רַבִּי שִׁמְעוֹן אוֹמֵר, הַבִּכּוּרִים נִתָּנִין לַכֹּהֲנִים כַּתְּרוּמָה. הַתַּבְשִׁיל, בֵּית שַׁמַּאי אוֹמְרִים, צָרִיךְ לְבַעֵר. וּבֵית הִלֵּל אוֹמְרִים, הֲרֵי הוּא כִּמְבֹעָר:",
      "מִי שֶׁהָיוּ לוֹ פֵרוֹת בַּזְּמָן הַזֶּה וְהִגִּיעָה שְׁעַת הַבִּעוּר, בֵּית שַׁמַּאי אוֹמְרִים, צָרִיךְ לְחַלְּלָן עַל הַכֶּסֶף. וּבֵית הִלֵּל אוֹמְרִים, אֶחָד שֶׁהֵן כֶּסֶף וְאֶחָד שֶׁהֵן פֵּרוֹת:",
      "אָמַר רַבִּי יְהוּדָה, בָּרִאשׁוֹנָה הָיוּ שׁוֹלְחִין אֵצֶל בַּעֲלֵי בָתִּים שֶׁבַּמְּדִינוֹת, מַהֲרוּ וְהַתְקִינוּ אֶת פֵּרוֹתֵיכֶם עַד שֶׁלֹּא תַגִּיעַ שְׁעַת הַבִּעוּר. עַד שֶׁבָּא רַבִּי עֲקִיבָא וְלִמֵּד, שֶׁכָּל הַפֵּרוֹת שֶׁלֹּא בָאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, פְּטוּרִים מִן הַבִּעוּר:",
      "מִי שֶׁהָיוּ פֵרוֹתָיו רְחוֹקִים מִמֶּנּוּ, צָרִיךְ לִקְרוֹא לָהֶם שֵׁם. מַעֲשֶׂה בְרַבָּן גַּמְלִיאֵל וְהַזְּקֵנִים שֶׁהָיוּ בָאִין בִּסְפִינָה, אָמַר רַבָּן גַּמְלִיאֵל, עִשּׂוּר שֶׁאֲנִי עָתִיד לָמוֹד, נָתוּן לִיהוֹשֻׁעַ, וּמְקוֹמוֹ מֻשְׂכָּר לוֹ. עִשּׂוּר אַחֵר שֶׁאֲנִי עָתִיד לָמֹד, נָתוּן לַעֲקִיבָא בֶן יוֹסֵף שֶׁיִּזְכֶּה בוֹ לָעֲנִיִּים, וּמְקוֹמוֹ מֻשְׂכָּר לוֹ. אָמַר רַבִּי יְהוֹשֻׁעַ, עִשּׂוּר שֶׁאֲנִי עָתִיד לָמוֹד נָתוּן לְאֶלְעָזָר בֶּן עֲזַרְיָה, וּמְקוֹמוֹ מֻשְׂכָּר לוֹ. וְנִתְקַבְּלוּ זֶה מִזֶּה שָׂכָר:",
      "בַּמִּנְחָה בְיוֹם טוֹב הָאַחֲרוֹן הָיוּ מִתְוַדִּין. כֵּיצַד הָיָה הַוִּדּוּי, בִּעַרְתִּי הַקֹּדֶשׁ מִן הַבַּיִת (דברים כו), זֶה מַעֲשֵׂר שֵׁנִי וְנֶטַע רְבָעִי. נְתַתִּיו לַלֵּוִי, זֶה מַעְשַׂר לֵוִי. וְגַם נְתַתִּיו, זוֹ תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר. לַגֵּר לַיָּתוֹם וְלָאַלְמָנָה, זֶה מַעֲשַׂר עָנִי, הַלֶּקֶט וְהַשִּׁכְחָה וְהַפֵּאָה, אַף עַל פִּי שֶׁאֵינָן מְעַכְּבִין אֶת הַוִּדּוּי. מִן הַבַּיִת, זוֹ חַלָּה:",
      "כְּכָל מִצְוָתְךָ אֲשֶׁר צִוִּיתָנִי (שם), הָא אִם הִקְדִּים מַעֲשֵׂר שֵׁנִי לָרִאשׁוֹן, אֵינוֹ יָכוֹל לְהִתְוַדּוֹת. לֹא עָבַרְתִּי מִמִּצְוֹתֶיךָ, לֹא הִפְרַשְׁתִּי מִמִּין עַל שֶׁאֵינוֹ מִינוֹ, וְלֹא מִן הַתָּלוּשׁ עַל הַמְחֻבָּר, וְלֹא מִן הַמְחֻבָּר עַל הַתָּלוּשׁ, וְלֹא מִן הֶחָדָשׁ עַל הַיָּשָׁן, וְלֹא מִן הַיָּשָׁן עַל הֶחָדָשׁ. וְלֹא שָׁכָחְתִּי, לֹא שָׁכַחְתִּי מִלְּבָרֶכְךָ וּמִלְּהַזְכִּיר שִׁמְךָ עָלָיו:",
      "לֹא אָכַלְתִּי בְאֹנִי מִמֶּנּוּ (שם), הָא אִם אֲכָלוֹ בַאֲנִינָה אֵינוֹ יָכוֹל לְהִתְוַדּוֹת. וְלֹא בִעַרְתִּי מִמֶּנּוּ בְּטָמֵא, הָא אִם הִפְרִישׁוֹ בְטֻמְאָה אֵינוֹ יָכוֹל לְהִתְוַדּוֹת. וְלֹא נָתַתִּי מִמֶּנּוּ לְמֵת, לֹא לָקַחְתִּי מִמֶּנּוּ אָרוֹן וְתַכְרִיכִים לְמֵת, וְלֹא נְתַתִּיו לְאוֹנְנִים אֲחֵרִים. שָׁמַעְתִּי בְקוֹל ה' אֱלֹהָי, הֲבֵאתִיו לְבֵית הַבְּחִירָה. עָשִׂיתִי כְּכֹל אֲשֶׁר צִוִּיתָנִי, שָׂמַחְתִּי וְשִׂמַּחְתִּי בוֹ:",
      "הַשְׁקִיפָה מִמְּעוֹן קָדְשְׁךָ מִן הַשָּׁמַיִם (דברים כו, טו), עָשִׂינוּ מַה שֶׁגָּזַרְתָּ עָלֵינוּ, אַף אַתָּה עֲשֵׂה מַה שֶׁהִבְטַחְתָּנוּ, הַשְׁקִיפָה מִמְּעוֹן קָדְשְׁךָ מִן הַשָּׁמַיִם וּבָרֵךְ אֶת עַמְּךָ אֶת יִשְׂרָאֵל בְּבָנִים וּבְבָנוֹת. וְאֵת הָאֲדָמָה אֲשֶׁר נָתַתָּה לָנוּ, בְּטַל וּבְמָטָר וּבְוַלְדוֹת בְּהֵמָה. כַּאֲשֶׁר נִשְׁבַּעְתָּ לַאֲבוֹתֵינוּ אֶרֶץ זָבַת חָלָב וּדְבָשׁ, כְּדֵי שֶׁתִּתֵּן טַעַם בַּפֵּרוֹת:",
      "מִכָּאן אָמְרוּ, יִשְׂרָאֵל וּמַמְזֵרִים מִתְוַדִּים, אֲבָל לֹא גֵרִים וְלֹא עֲבָדִים מְשֻׁחְרָרִים, שֶׁאֵין לָהֶם חֵלֶק בָּאָרֶץ. רַבִּי מֵאִיר אוֹמֵר, אַף לֹא כֹהֲנִים וּלְוִיִּם, שֶׁלֹּא נָטְלוּ חֵלֶק בָּאָרֶץ. רַבִּי יוֹסֵי אוֹמֵר, יֵשׁ לָהֶם עָרֵי מִגְרָשׁ:",
      "יוֹחָנָן כֹּהֵן גָּדוֹל הֶעֱבִיר הוֹדָיוֹת הַמַּעֲשֵׂר. אַף הוּא בִּטֵּל אֶת הַמְעוֹרְרִים, וְאֶת הַנּוֹקְפִים. וְעַד יָמָיו הָיָה פַטִּישׁ מַכֶּה בִירוּשָׁלָיִם, וּבְיָמָיו אֵין אָדָם צָרִיךְ לִשְׁאוֹל עַל הַדְּמָאי:"
